import java.util.Locale;
import java.util.concurrent.CompletableFuture;

/**
 * TASK: Combine two asynchronous results with CompletableFuture.
 *
 * A quote is made of two independent lookups that should run at the same time:
 *   subtotal = itemCents * quantity
 *   shipping = 0 when quantity >= 10, otherwise 499
 *
 * quoteCents(itemCents, quantity) must:
 *   1. start the subtotal with CompletableFuture.supplyAsync(...)
 *   2. start the shipping with a SECOND CompletableFuture.supplyAsync(...)
 *   3. join them with thenCombine so the total is subtotal + shipping
 *   4. return the combined value with join()
 *
 * quoteLabel(itemCents, quantity) must reuse the SAME combined future and add a
 * thenApply step that formats the total as dollars, then join() it:
 *   1234 cents -> "$12.34"      499 cents -> "$4.99"      0 cents -> "$0.00"
 * Use String.format(Locale.US, "$%d.%02d", cents / 100, cents % 100) -- no doubles.
 *
 * Example: quoteCents(1000, 2) -> 2000 + 499 -> 2499, quoteLabel(1000, 2) -> "$24.99"
 */
public class AsyncPriceCombiner {

    private static CompletableFuture<Integer> totalFuture(int itemCents, int quantity) {
        CompletableFuture<Integer> subtotal =
                CompletableFuture.supplyAsync(() -> itemCents * quantity);
        CompletableFuture<Integer> shipping =
                CompletableFuture.supplyAsync(() -> quantity >= 10 ? 0 : 499);
        return subtotal.thenCombine(shipping, (a, b) -> a + b);
    }

    public static int quoteCents(int itemCents, int quantity) {
        return totalFuture(itemCents, quantity).join();
    }

    public static String quoteLabel(int itemCents, int quantity) {
        return totalFuture(itemCents, quantity)
                .thenApply(cents -> String.format(Locale.US, "$%d.%02d", cents / 100, cents % 100))
                .join();
    }
}
